create table xxcus.xxcmp_questions (
    question_id           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    questionnaire_code    varchar2(30 byte) not null enable,
    section_name          varchar2(240 byte),
    question_text         varchar2(2000 byte) not null enable,
    answer_type           varchar2(30 byte) not null enable,
    lookup_type           varchar2(30 byte),
    gate_question_flag    varchar2(1 byte) default 'N' not null enable,
    required_flag         varchar2(1 byte) default 'Y' not null enable,
    display_sequence      number,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_questions
    add constraint xxcmp_questions_ck1
        check ( answer_type in ( 'SINGLE_SELECT', 'MULTI_SELECT', 'YES_NO', 'TEXT', 'NUMBER',
                                 'DATE' ) ) enable;

alter table xxcus.xxcmp_questions
    add constraint xxcmp_questions_ck2
        check ( gate_question_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_questions
    add constraint xxcmp_questions_ck3
        check ( required_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_questions
    add constraint xxcmp_questions_ck4
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_questions
    add constraint xxcmp_questions_pk primary key ( question_id )
        using index enable;


